    return Command(
        glom_cli,
        [
            Flag('--help', '-h', dest='help', action='store_true'),
            Flag('--target-file', dest='target_file'),
            Flag('--target-format', dest='target_format', default='json'),
            Flag('--spec-file', dest='spec_file'),
            Flag('--spec-format', dest='spec_format', default='python'),
            Flag('--indent', dest='indent', type=int, default=2),
            Flag('--debug', dest='debug', action='store_true'),
