            Flag('--scalar', dest='scalar', action='store_true'),
        ],
        [
            PosArgSpec('spec', display=PosArgDisplay.STRING),
            PosArgSpec('target', display=PosArgDisplay.STRING),
        ],
        middleware=[
            mw_get_target,
            mw_handle_target,
        ],
    )


def main(argv):
    cmd = get_command()
    try:
        args = cmd.parse(argv[1:])
    except UsageError as e:
        print(str(e), file=sys.stderr)
        return 1
    except CommandLineError as e:
        print(str(e), file=sys.stderr)
        return 1

    return cmd.run(args)


def mw_handle_target(target_text, target_format):
    if target_text is None:
        return {'target': {}}

    if target_format == 'json':
        target = json.loads(target_text)
    elif target_format == 'python':
        target = ast.literal_eval(target_text)
    elif target_format == 'yaml':
        import yaml
        target = yaml.safe_load(target_text)
    elif target_format == 'toml':
        import toml
        target = toml.loads(target_text)
    else:
        raise CommandLineError('target-format to be one of: json, python, yaml, toml')

    return {'target': target}


@face_middleware(provides=['spec', 'target'])
def mw_get_target(next_, posargs_, target_file, target_format, spec_file,
    spec_format):
    # Get spec
    if spec_file:
        with open(spec_file, 'r') as f:
            spec_text = f.read()
    else:
        spec_text = posargs_[0] if posargs_ else ''

    # Get target
